import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().splitlines()
    idx = 0

    while idx < len(input_data) and not input_data[idx].strip():
        idx += 1

    if idx >= len(input_data):
        return

    parts = input_data[idx].split()
    n, m, k = int(parts[0]), int(parts[1]), int(parts[2])
    idx += 1

    pictures = []
    for _ in range(k + 1):
        while idx < len(input_data) and not input_data[idx].strip(): idx += 1
        pic = []
        for _ in range(n):
            pic.append(list(input_data[idx]))
            idx += 1
        pictures.append(pic)

    def count_ones(p):
        c = 0
        for r in p:
            for x in r:
                if x == '1':
                    c += 1
        return c

    def can_recolor(p, r, c):
        if r == 0 or r == n - 1 or c == 0 or c == m - 1:
            return False
        center = p[r][c]
        neighbors = [p[r-1][c], p[r+1][c], p[r][c-1], p[r][c+1]]
        opp = '1' if center == '0' else '0'
        return all(x == opp for x in neighbors)

    def apply_recolor(p, r, c):
        new_p = [row[:] for row in p]
        new_p[r][c] = '1' if new_p[r][c] == '0' else '0'
        return new_p

    def pictures_equal(p1, p2):
        return p1 == p2

    initial_idx = -1
    min_ones = float('inf')

    for i in range(k + 1):
        ones = count_ones(pictures[i])
        if ones < min_ones:
            min_ones = ones
            initial_idx = i
        elif ones == min_ones:
            pass

    used = [False] * (k + 1)
    used[initial_idx] = True

    current_pic = [row[:] for row in pictures[initial_idx]]
    operations = []

    pending_copies = {}

    for i in range(k + 1):
        if i != initial_idx:
            pending_copies[i] = pictures[i]

    while len(pending_copies) > 0:
        found_op = False
        target_pic = None
        target_idx = None

        for i, target in pending_copies.items():
            if pictures_equal(current_pic, target):
                target_pic = target
                target_idx = i
                break

        if target_pic is not None:
            operations.append(f"2 {target_idx}")
            del pending_copies[target_idx]
            found_op = True
            continue

        for r in range(1, n - 1):
            for c in range(1, m - 1):
                if can_recolor(current_pic, r, c):
                    new_pic = apply_recolor(current_pic, r, c)
                    for i, target in pending_copies.items():
                        if pictures_equal(new_pic, target):
                            operations.append(f"1 {r + 1} {c + 1}")
                            current_pic = new_pic
                            found_op = True
                            break
                    if found_op:
                        break
            if found_op:
                break

        if not found_op:
            break

    print(initial_idx + 1)
    print(len(operations))
    for op in operations:
        print(op)

if __name__ == "__main__":
    solve()
